49	async function maRequest<T = unknown>(
50	  method: 'GET' | 'POST' | 'DELETE',
51	  path: string,
52	  body?: unknown,
53	): Promise<{ ok: true; status: number; data: T } | { ok: false; status: number; error: string; body?: unknown }> {
54	  const key = apiKey();
55	  if (!key) return { ok: false, status: 0, error: NEEDS_KEY.error };
56	  let res: Response;
57	  try {
58	    res = await fetch(`${API_BASE}/v1${path}`, {
59	      method,
60	      headers: headers(key),
61	      body: body !== undefined ? JSON.stringify(body) : undefined,
62	      signal: AbortSignal.timeout(30_000),
63	    });
64	  } catch (e) {
65	    return { ok: false, status: 0, error: `network error calling ${method} /v1${path}: ${(e as Error).message}` };
66	  }
67	  const text = await res.text();
68	  let parsed: unknown = undefined;
69	  try { parsed = text ? JSON.parse(text) : undefined; } catch { /* leave undefined */ }
70	  if (!res.ok) {
71	    const apiErr = (parsed as { error?: { message?: string }; message?: string })?.error?.message
72	      ?? (parsed as { message?: string })?.message
73	      ?? text.slice(0, 300);
74	    return { ok: false, status: res.status, error: `Managed Agents API ${res.status}: ${apiErr}`, body: parsed };
75	  }
76	  return { ok: true, status: res.status, data: parsed as T };
77	}
